import os
import joblib
import pandas as pd
import mlflow
import mlflow.sklearn
from sklearn.compose import ColumnTransformer
from sklearn.preprocessing import StandardScaler, OneHotEncoder
from sklearn.pipeline import Pipeline
from sklearn.model_selection import GridSearchCV
from sklearn.metrics import accuracy_score, precision_score, recall_score, f1_score, roc_auc_score
import xgboost as xgb

def main():
    # 1. Load train and test splits generated by prep.py
    print("Loading data splits...")
    X_train = pd.read_csv("Xtrain.csv")
    X_test = pd.read_csv("Xtest.csv")
    y_train = pd.read_csv("ytrain.csv").values.ravel()
    y_test = pd.read_csv("ytest.csv").values.ravel()

    # 2. Identify categorical and numerical columns
    cat_cols = X_train.select_dtypes(include=['object', 'category']).columns.tolist()
    num_cols = X_train.select_dtypes(include=['int64', 'float64']).columns.tolist()

    # 3. Create preprocessing pipeline
    preprocessor = ColumnTransformer(
        transformers=[
            ('num', StandardScaler(), num_cols),
            ('cat', OneHotEncoder(handle_unknown='ignore'), cat_cols)
        ]
    )

    # 4. Define base XGBoost classifier model pipeline
    full_pipeline = Pipeline([
        ('preprocessor', preprocessor),
        ('classifier', xgb.XGBClassifier(random_state=42, eval_metric='logloss'))
    ])

    # 5. Define Hyperparameter Grid for tuning
    param_grid = {
        'classifier__n_estimators': [50, 100],
        'classifier__max_depth': [3, 5],
        'classifier__learning_rate': [0.05, 0.1]
    }

    # 6. Set up MLflow Experiment Tracking
    mlflow.set_experiment("Wellness_Tourism_Package_Prediction")

    with mlflow.start_run(run_name="XGBoost_GridSearch_Tuning"):
        print("Starting hyperparameter tuning with GridSearchCV...")
        grid_search = GridSearchCV(
            estimator=full_pipeline,
            param_grid=param_grid,
            cv=3,
            scoring='f1',
            n_jobs=-1
        )
        grid_search.fit(X_train, y_train)

        best_model = grid_search.best_estimator_
        best_params = grid_search.best_params_

        # 7. Evaluate Best Model on Test Set
        y_pred = best_model.predict(X_test)
        y_proba = best_model.predict_proba(X_test)[:, 1]

        acc = accuracy_score(y_test, y_pred)
        prec = precision_score(y_test, y_pred, zero_division=0)
        rec = recall_score(y_test, y_pred, zero_division=0)
        f1 = f1_score(y_test, y_pred, zero_division=0)
        auc = roc_auc_score(y_test, y_proba)

        # Log parameters and metrics to MLflow
        mlflow.log_params(best_params)
        mlflow.log_metrics({
            "accuracy": acc,
            "precision": prec,
            "recall": rec,
            "f1_score": f1,
            "roc_auc": auc
        })

        print("\n--- Model Evaluation ---")
        print(f"Best Params: {best_params}")
        print(f"Accuracy  : {acc:.4f}")
        print(f"Precision : {prec:.4f}")
        print(f"Recall    : {rec:.4f}")
        print(f"F1 Score  : {f1:.4f}")
        print(f"ROC-AUC   : {auc:.4f}")

        # Log model artifact to MLflow
        mlflow.sklearn.log_model(best_model, artifact_path="model")

        # 8. Save the best model locally for Streamlit deployment & GitHub Actions commit
        model_save_path = "tourism_project/deployment/model.joblib"
        joblib.dump(best_model, model_save_path)
        print(f"\nBest model saved to: {model_save_path}")

if __name__ == "__main__":
    main()
